	local __knRepoPrefixes = {
		"https://raw.githubusercontent.com/flazhy/QuantumOnyx/",
		"https://raw.githubusercontent.com/flazhy/QuantumOnyx/refs/heads/main/",
		"https://raw.githubusercontent.com/flazhy/QuantumOnyx/main/",
	}

	local function __knResolve(url)
		if type(url) ~= "string" then
			return nil
		end

		for _, p in ipairs(__knRepoPrefixes) do
			if url:sub(1, #p) == p then
				local rel = url:sub(#p + 1)

				if __knFiles[rel] then
					return __knFiles[rel]
				end
			end
		end

		if __knFiles[url] then
			return __knFiles[url]
		end

		return nil
	end

	-- safety net: any HttpGet to the repo is served from the local pack
	pcall(function()
		if hookfunction and type(game.HttpGet) == "function" then
			local __knOrigHttpGet = game.HttpGet

			hookfunction(__knOrigHttpGet, function(self, url, ...)
				local hit = __knResolve(url)

				if hit then
					return hit
				end

				return __knOrigHttpGet(self, url, ...)
			end)
		end
	end)

	local function __knLoad(code)
		if type(code) ~= "string" then
			return nil
		end

		local ok, res = pcall(function()
			local f = loadstring(code)

			if f then
				return f()
			end
		end)

		if ok then
			return res
		end

		return nil
