	mods.CoreSetup = function(arg)
		if arg.SetupData then
			arg:SetupData()
		end
	end

	mods.CombatHooks = function(arg)
		if arg.LoadFunctions then
			arg:LoadFunctions()
		end
	end

	mods.RuntimeServices = function(arg)
		if arg.LoadLoops then
			arg:LoadLoops()
		end
	end

	local function fn27(arg, ...)
		local now = tick()
		local v22 = mods[arg]

		if v22 then
			v22(mods, ...)
		end

		print(string.format("[Quantum Onyx] %s initialized in %.4fs", arg, tick() - now))
	end

	-- [patched] init steps are guarded: one failing phase can no longer stop
	-- the rest (and the menu) from loading
	pcall(fn27, "CoreSetup")
	pcall(fn27, "CombatHooks")
	pcall(fn27, "RuntimeServices")

	task.spawn(function()
		local ok, err = pcall(fn27, "LoadLibrary")

		if not ok then
			warn("[Quantum Onyx] LoadLibrary failed: " .. tostring(err))

			pcall(function()
				mods:SendNotify("Quantum Onyx - Load Error", tostring(err), 12)
			end)
		end
	end)

	task.spawn(function()
		task.wait(1.5)
		mods:SendNotify("Quantum Fully Loaded", "All Functions, Modules, Dependencies, Successfully loaded.", 8)
		task.wait(1)
		mods:SendNotify("Quantum (INFO)", "Quantum Onyx Script is 100% Free and Keyless", 8)

		-- [patched] OFFLINE: Weebo served from the embedded pack
		pcall(function()
			loadstring(__knFiles["Util/BloxFruitModule/Preload/Weebo.lua"])()
		end)
	end)

	return
end
